-- ── admin_add_coaching_student(text,uuid,jsonb) ─────────────────
CREATE OR REPLACE FUNCTION public.admin_add_coaching_student(p_caller text, p_centre_id uuid, p_fields jsonb)
 RETURNS coaching_students
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_row coaching_students;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;
  insert into coaching_students (centre_id, firebase_uid, name, email, target_exam, student_name, student_email, batch)
  values (p_centre_id, p_fields->>'firebase_uid', p_fields->>'name', p_fields->>'email',
          p_fields->>'target_exam', p_fields->>'student_name', p_fields->>'student_email', p_fields->>'batch')
  returning * into v_row;
  return v_row;
end; $function$;

-- ── admin_bulk_upsert_test_users(text,jsonb) ────────────────────
CREATE OR REPLACE FUNCTION public.admin_bulk_upsert_test_users(p_caller text, p_rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;
  insert into public.users (firebase_uid, display_name, email, target_exam, syllabus, class_level, onboarding_completed, auth_method)
  select
    r->>'firebase_uid', r->>'display_name', r->>'email', r->>'target_exam',
    r->>'syllabus', r->>'class_level',
    coalesce((r->>'onboarding_completed')::boolean, true),
    coalesce(r->>'auth_method', 'google')
  from jsonb_array_elements(p_rows) r
  on conflict (firebase_uid) do update set
    display_name = excluded.display_name, email = excluded.email,
    target_exam = excluded.target_exam, syllabus = excluded.syllabus,
    class_level = excluded.class_level;
end; $function$;

