-- ── admin_delete_test_rows(text,text,text,text[]) ───────────────
CREATE OR REPLACE FUNCTION public.admin_delete_test_rows(p_caller text, p_table text, p_col text, p_values text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;

  if p_table not in (
    'question_history', 'user_weak_topics', 'user_gamification',
    'daily_usage_quota', 'flashcards', 'notification_prefs', 'users',
    'coaching_centres'
  ) then
    raise exception 'Table not allowed for this operation';
  end if;
  if p_col not in ('user_id', 'firebase_uid', 'name') then
    raise exception 'Column not allowed for this operation';
  end if;

  execute format('delete from public.%I where %I = any($1)', p_table, p_col) using p_values;
end; $function$;

-- ── admin_delete(text,text) ─────────────────────────────────────
CREATE OR REPLACE FUNCTION public.admin_delete(p_caller text, p_target_uid text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_caller_role TEXT;
  v_target_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_caller_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_caller_role IS DISTINCT FROM 'superadmin' THEN
    RETURN json_build_object('error', 'Unauthorized');
  END IF;
  IF p_caller = p_target_uid THEN
    RETURN json_build_object('error', 'Cannot delete your own account');
  END IF;
  SELECT role INTO v_target_role FROM admins WHERE uid = p_target_uid;
  IF v_target_role = 'superadmin' THEN
    RETURN json_build_object('error', 'Cannot delete another superadmin');
  END IF;
  DELETE FROM admins WHERE uid = p_target_uid;
  RETURN json_build_object('ok', true);
END;
$function$;

-- ── admin_grant_subscription(text,text,text,integer) ────────────
CREATE OR REPLACE FUNCTION public.admin_grant_subscription(p_caller text, p_user_id text, p_plan text, p_days integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin') THEN RAISE EXCEPTION 'Access denied'; END IF;

  INSERT INTO subscriptions (user_id, plan, status, starts_at, expires_at, updated_at)
  VALUES (p_user_id, p_plan, 'active', NOW(), NOW() + (p_days||' days')::INTERVAL, NOW())
  ON CONFLICT (user_id) DO UPDATE SET
    plan       = EXCLUDED.plan,
    status     = 'active',
    starts_at  = NOW(),
    expires_at = NOW() + (p_days||' days')::INTERVAL,
    updated_at = NOW();

  RETURN json_build_object('ok', true);
END;
$function$;

-- ── admin_publish_test(text,jsonb) ──────────────────────────────
CREATE OR REPLACE FUNCTION public.admin_publish_test(p_caller text, p_fields jsonb)
 RETURNS published_tests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.published_tests;
  v_created_by text;
  v_user_id text;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  if not public.is_active_admin(p_caller) then
    raise exception 'Access denied';
  end if;

  v_created_by := coalesce(p_fields->>'created_by', 'admin');
  v_user_id := nullif(p_fields->>'user_id', '');
  if v_created_by = 'student' and v_user_id is null then
    raise exception 'student-owned published tests must include user_id';
  end if;

  insert into public.published_tests (
    title, subject, exam_type, difficulty, questions,
    duration_minutes, is_published, question_count,
    blueprint_match_pct, created_by, user_id
  ) values (
    p_fields->>'title', p_fields->>'subject', p_fields->>'exam_type', p_fields->>'difficulty',
    coalesce(p_fields->'questions', '[]'::jsonb),
    (p_fields->>'duration_minutes')::int, true,
    coalesce(jsonb_array_length(coalesce(p_fields->'questions', '[]'::jsonb)), 0),
    (p_fields->>'blueprint_match_pct')::numeric, v_created_by, v_user_id
  ) returning * into v_row;

  return v_row;
end;
$function$;

