AS $function$
BEGIN

  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS (
    SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true
  ) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  INSERT INTO feature_flags (key, enabled)
  VALUES (p_key, p_enabled)
  ON CONFLICT (key) DO UPDATE SET enabled = EXCLUDED.enabled;
END;
$function$;

-- ── admin_upsert_coaching_assignment(text,uuid,uuid,jsonb) ──────
CREATE OR REPLACE FUNCTION public.admin_upsert_coaching_assignment(p_caller text, p_centre_id uuid, p_id uuid DEFAULT NULL::uuid, p_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS coaching_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_row coaching_assignments;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;

  if p_id is null then
    insert into coaching_assignments (centre_id, title, exam_type, subject, due_date, questions, description)
    values (p_centre_id, p_fields->>'title', p_fields->>'exam_type', p_fields->>'subject',
            (p_fields->>'due_date')::date, coalesce(p_fields->'questions', '[]'::jsonb), p_fields->>'description')
    returning * into v_row;
  else
    update coaching_assignments set
      title = coalesce(p_fields->>'title', title),
      exam_type = coalesce(p_fields->>'exam_type', exam_type),
      subject = coalesce(p_fields->>'subject', subject),
      due_date = coalesce((p_fields->>'due_date')::date, due_date),
      questions = coalesce(p_fields->'questions', questions),
      description = coalesce(p_fields->>'description', description),
      updated_at = now()
    where id = p_id and centre_id = p_centre_id
    returning * into v_row;
  end if;
  return v_row;
end; $function$;

-- ── admin_upsert_coaching_centre(text,uuid,jsonb) ───────────────
CREATE OR REPLACE FUNCTION public.admin_upsert_coaching_centre(p_caller text, p_id uuid DEFAULT NULL::uuid, p_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS coaching_centres
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_row coaching_centres;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;
  if p_id is null then
    insert into coaching_centres select * from jsonb_populate_record(null::coaching_centres, p_fields) returning * into v_row;
  else
    update coaching_centres set
      name = coalesce(p_fields->>'name', name),
      city = coalesce(p_fields->>'city', city),
      contact_email = coalesce(p_fields->>'contact_email', contact_email),
      contact_phone = coalesce(p_fields->>'contact_phone', contact_phone),
      plan = coalesce(p_fields->>'plan', plan),
      max_students = coalesce((p_fields->>'max_students')::int, max_students),
      status = coalesce(p_fields->>'status', status),
      notes = coalesce(p_fields->>'notes', notes),
      brand_color = coalesce(p_fields->>'brand_color', brand_color),
      website_url = coalesce(p_fields->>'website_url', website_url),
      phone = coalesce(p_fields->>'phone', phone),
      tagline = coalesce(p_fields->>'tagline', tagline),
      updated_at = now()
    where id = p_id
    returning * into v_row;
  end if;
  return v_row;
end; $function$;

-- ── admin_upsert_exam_category(text,uuid,text,text,text,text,text,text,text[],integer) 
CREATE OR REPLACE FUNCTION public.admin_upsert_exam_category(p_caller text, p_id uuid, p_exam_key text, p_label text, p_category_kind text, p_board_key text, p_class_key text, p_group_label text, p_subjects text[], p_sort_order integer)
 RETURNS exam_categories
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_row exam_categories;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS(SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO exam_categories (exam_key, label, category_kind, board_key, class_key, group_label, subjects, sort_order)
    VALUES (p_exam_key, p_label, p_category_kind, p_board_key, p_class_key, p_group_label, COALESCE(p_subjects, '{}'), COALESCE(p_sort_order, 0))
    ON CONFLICT (exam_key) DO UPDATE SET
      label = EXCLUDED.label, category_kind = EXCLUDED.category_kind, board_key = EXCLUDED.board_key,
      class_key = EXCLUDED.class_key, group_label = EXCLUDED.group_label, subjects = EXCLUDED.subjects,
      sort_order = EXCLUDED.sort_order, is_active = true, updated_at = now()
    RETURNING * INTO v_row;
  ELSE
    UPDATE exam_categories SET
      exam_key = p_exam_key, label = p_label, category_kind = p_category_kind,
      board_key = p_board_key, class_key = p_class_key, group_label = p_group_label,
      subjects = COALESCE(p_subjects, '{}'), sort_order = COALESCE(p_sort_order, 0), updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END;
$function$;

-- ── admin_upsert_onboarding_option(text,uuid,text,text,text[],text,text,text,text,integer,boolean,boolean,boolean,text,text[]) 
CREATE OR REPLACE FUNCTION public.admin_upsert_onboarding_option(p_caller text, p_id uuid, p_option_type text, p_option_key text, p_category_keys text[], p_title text, p_description text, p_icon_name text, p_color text, p_sort_order integer, p_is_active boolean, p_needs_board boolean DEFAULT false, p_needs_class boolean DEFAULT false, p_default_class_level text DEFAULT NULL::text, p_allowed_class_levels text[] DEFAULT '{}'::text[])
 RETURNS onboarding_category_display
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_row onboarding_category_display;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;

  insert into onboarding_category_display (
    id, option_type, option_key, category_keys, title, description,
    icon_name, color, sort_order, is_active, needs_board, needs_class,
    default_class_level, allowed_class_levels, updated_at
  )
  values (
    coalesce(p_id, gen_random_uuid()), p_option_type, p_option_key, p_category_keys,
    p_title, p_description, p_icon_name, p_color, p_sort_order, p_is_active,
    p_needs_board, p_needs_class, p_default_class_level, coalesce(p_allowed_class_levels, '{}'), now()
  )
  on conflict (id) do update set
    option_type = excluded.option_type, option_key = excluded.option_key,
    category_keys = excluded.category_keys, title = excluded.title,
    description = excluded.description, icon_name = excluded.icon_name,
    color = excluded.color, sort_order = excluded.sort_order,
    is_active = excluded.is_active, needs_board = excluded.needs_board,
    needs_class = excluded.needs_class, default_class_level = excluded.default_class_level,
    allowed_class_levels = excluded.allowed_class_levels,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$;

