-- ── admin_upsert_study_note(text,uuid,text,text,text,text,text,text,uuid,boolean,text[],text,integer,integer,integer,text) 
CREATE OR REPLACE FUNCTION public.admin_upsert_study_note(p_caller text, p_id uuid DEFAULT NULL::uuid, p_title text DEFAULT ''::text, p_subject text DEFAULT NULL::text, p_exam_type text DEFAULT NULL::text, p_chapter text DEFAULT NULL::text, p_content text DEFAULT NULL::text, p_pdf_url text DEFAULT NULL::text, p_centre_id uuid DEFAULT NULL::uuid, p_is_published boolean DEFAULT false, p_tags text[] DEFAULT '{}'::text[], p_unit text DEFAULT NULL::text, p_page_start integer DEFAULT NULL::integer, p_page_end integer DEFAULT NULL::integer, p_sort_order integer DEFAULT 0, p_source_text text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role TEXT; v_id UUID; result JSON;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin') THEN RAISE EXCEPTION 'Access denied'; END IF;

  IF p_id IS NOT NULL THEN
    UPDATE study_notes SET
      title = p_title, subject = p_subject, exam_type = p_exam_type,
      chapter = p_chapter, content = p_content, pdf_url = p_pdf_url,
      centre_id = p_centre_id, is_published = p_is_published,
      tags = p_tags, unit = p_unit, page_start = p_page_start,
      page_end = p_page_end, sort_order = p_sort_order,
      source_text = p_source_text, updated_at = NOW()
    WHERE id = p_id RETURNING id INTO v_id;
  ELSE
    INSERT INTO study_notes
      (title, subject, exam_type, chapter, content, pdf_url, centre_id, is_published, tags, created_by, unit, page_start, page_end, sort_order, source_text)
    VALUES (p_title, p_subject, p_exam_type, p_chapter, p_content, p_pdf_url, p_centre_id, p_is_published, p_tags, p_caller, p_unit, p_page_start, p_page_end, p_sort_order, p_source_text)
    RETURNING id INTO v_id;
  END IF;

  SELECT row_to_json(n) INTO result FROM study_notes n WHERE n.id = v_id;
  RETURN result;
END;
$function$;

-- ── admin_upsert_syllabus_node(text,text,text,text,text,text,integer,jsonb,uuid) 
CREATE OR REPLACE FUNCTION public.admin_upsert_syllabus_node(p_caller text, p_exam_type text, p_subject text, p_chapter_name text, p_chapter_key text, p_class_level text DEFAULT NULL::text, p_sort_order integer DEFAULT 1, p_subtopics jsonb DEFAULT '[]'::jsonb, p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row syllabus_nodes%ROWTYPE;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS (SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE syllabus_nodes SET
      chapter_name = p_chapter_name,
      sort_order   = p_sort_order,
      subtopics    = p_subtopics,
      is_active    = true
    WHERE id = p_id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO syllabus_nodes
      (exam_type, subject, chapter_key, chapter_name, class_level, sort_order, subtopics)
    VALUES
      (p_exam_type, p_subject, p_chapter_key, p_chapter_name, p_class_level, p_sort_order, p_subtopics)
    ON CONFLICT (exam_type, subject, chapter_key) DO UPDATE SET
      chapter_name = EXCLUDED.chapter_name,
      sort_order   = EXCLUDED.sort_order,
      subtopics    = EXCLUDED.subtopics
    RETURNING * INTO v_row;
  END IF;

  RETURN row_to_json(v_row)::jsonb;
END;
$function$;

-- ── admin_upsert_test_assignment(text,jsonb,uuid) ───────────────
CREATE OR REPLACE FUNCTION public.admin_upsert_test_assignment(p_caller text, p_fields jsonb, p_id uuid DEFAULT NULL::uuid)
 RETURNS test_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.test_assignments;
  v_test_id uuid;
  v_assigned_to_user_uid text;
  v_target_exam text;
  v_target_syllabus text;
  v_target_class_level text;
  v_note text;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  if not public.is_active_admin(p_caller) then
    raise exception 'Access denied';
  end if;

  v_assigned_to_user_uid := nullif(p_fields->>'assigned_to_user_uid', '');
  v_target_exam := nullif(p_fields->>'target_exam', '');
  v_target_syllabus := nullif(p_fields->>'target_syllabus', '');
  v_target_class_level := nullif(p_fields->>'target_class_level', '');
  v_note := nullif(p_fields->>'note', '');

  if p_id is null then
    v_test_id := (p_fields->>'test_id')::uuid;
    if v_test_id is null then
      raise exception 'test_id is required';
    end if;
    if v_assigned_to_user_uid is null and v_target_exam is null
       and v_target_syllabus is null and v_target_class_level is null then
      raise exception 'at least one assignment target is required';
    end if;

    insert into public.test_assignments (
      created_by, test_id, assigned_to_user_uid,
      target_exam, target_syllabus, target_class_level,
      is_active, expires_at, note
    ) values (
      p_caller, v_test_id, v_assigned_to_user_uid,
      v_target_exam, v_target_syllabus, v_target_class_level,
      coalesce((p_fields->>'is_active')::boolean, true),
      nullif(p_fields->>'expires_at', '')::timestamptz,
      v_note
    ) returning * into v_row;
  else
    update public.test_assignments set
      assigned_to_user_uid = coalesce(v_assigned_to_user_uid, assigned_to_user_uid),
      target_exam = coalesce(v_target_exam, target_exam),
      target_syllabus = coalesce(v_target_syllabus, target_syllabus),
      target_class_level = coalesce(v_target_class_level, target_class_level),
      is_active = coalesce((p_fields->>'is_active')::boolean, is_active),
      expires_at = coalesce(nullif(p_fields->>'expires_at', '')::timestamptz, expires_at),
      note = coalesce(v_note, note),
      updated_at = now()
    where id = p_id
    returning * into v_row;

    if not found then
      raise exception 'assignment % not found', p_id;
    end if;
  end if;

  return v_row;
end;
$function$;

-- ── admin_upsert(text,text,text,text,text,text) ─────────────────
CREATE OR REPLACE FUNCTION public.admin_upsert(p_caller text, p_uid text, p_email text, p_name text, p_role text, p_passcode text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_role IS DISTINCT FROM 'superadmin' THEN
    RETURN json_build_object('error', 'Unauthorized');
  END IF;
  IF length(p_passcode) <> 6 OR p_passcode !~ '^\d{6}$' THEN
    RETURN json_build_object('error', 'Passcode must be exactly 6 digits');
  END IF;
  INSERT INTO admins (uid, email, name, role, passcode_hash, added_by)
  VALUES (p_uid, p_email, p_name, p_role,
          encode(sha256(p_passcode::bytea), 'hex'), p_caller)
  ON CONFLICT (uid) DO UPDATE SET
    email         = EXCLUDED.email,
    name          = EXCLUDED.name,
    role          = EXCLUDED.role,
    passcode_hash = EXCLUDED.passcode_hash,
    updated_at    = NOW();
  RETURN json_build_object('ok', true);
END;
$function$;

-- ── coaching_admin_delete(text,text) ────────────────────────────
CREATE OR REPLACE FUNCTION public.coaching_admin_delete(p_caller text, p_target_uid text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  caller_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO caller_role FROM admins WHERE uid = p_caller AND is_active = true LIMIT 1;
  IF caller_role IS NULL OR caller_role NOT IN ('superadmin','admin') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  DELETE FROM coaching_admins WHERE uid = p_target_uid;
END;
$function$;

-- ── coaching_admin_upsert(text,text,text,text,uuid,text) ────────
CREATE OR REPLACE FUNCTION public.coaching_admin_upsert(p_caller text, p_uid text, p_email text, p_name text, p_centre_id uuid, p_role text DEFAULT 'instructor'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  caller_role TEXT;
  result      JSON;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO caller_role FROM admins WHERE uid = p_caller AND is_active = true LIMIT 1;
  IF caller_role IS NULL OR caller_role NOT IN ('superadmin','admin') THEN
    RAISE EXCEPTION 'Only platform admins can add coaching admins';
  END IF;

  INSERT INTO coaching_admins (uid, email, name, centre_id, role, added_by)
  VALUES (p_uid, p_email, p_name, p_centre_id, p_role, p_caller)
  ON CONFLICT (uid) DO UPDATE
    SET email     = EXCLUDED.email,
        name      = EXCLUDED.name,
        centre_id = EXCLUDED.centre_id,
        role      = EXCLUDED.role;

  SELECT row_to_json(r) INTO result
  FROM (SELECT * FROM coaching_admins WHERE uid = p_uid LIMIT 1) r;

  RETURN result;
END;
$function$;

commit;
